"use strict";
/* Basis pengetahuan Tanya Jawab. fq = Fathul Qorib (bab najis, hlm. 41-46). rm = Risalatul Mahidl (hlm. 10-45). Teks diambil dari PDF kitab, hanya terjemah/bahasa Indonesia. */
const KITAB = [{"k":"fq","h":41,"t":"(Fasal) menjelaskan najis dan menghilangkannya. Di dalam sebagian redaksi, fasal ini disebutkan sebelum \"Kitab Sholat\"."},{"k":"fq","h":41,"t":"Najis secara bahasa adalah sesuatu yang dianggap menjijikkan. Dan secara syara’ adalah setiap benda yang haram digunakan secara mutlak dalam keadaan normal beserta mudah untuk dibedakan, bukan karena kemuliannya, menjijikkannya dan bukan karena berbahaya pada badan atau akal."},{"k":"fq","h":41,"t":"Dengan bahasa \"dalam keadaan normal\" mengecualikan keadaan darurat. Karena sesungguhnya keadaan darurat memperbolehkan untuk menggunakan najis."},{"k":"fq","h":41,"t":"Dengan bahasa \"mudah dipisahkan\" mengecualikan memakan ulat yang mati di dalam keju, buah dan sesamanya."},{"k":"fq","h":41,"t":"Dengan ungkapan mushannif \"bukan karena kemuliannya\" mengecualikan mayatnya anak Adam."},{"k":"fq","h":41,"t":"Dengan keterangan \"tidak karena menjijikkan\" mengecualikan sperma dan sesamanya."},{"k":"fq","h":41,"t":"Dengan bahasa \"tidak karena membahayakan\" mengecualikan batu dan tanaman yang berbahaya pada badan atau akal. Maksudnya, semua barang-barang yang dikecualikan tersebut adalah barang-barang yang haram digunakan bukan karena najis tapi karena hal-hal yang telah disebutkan."},{"k":"fq","h":41,"t":"Macam-Macam Najis Kemudian mushannif menyebutkan batasan najis yang keluar dari qubul (jalur depan) dan dubur (jalur belakang) dengan perkataan beliau,"},{"k":"fq","h":41,"t":"Setiap benda cair yang keluar dari dua jalan hukumnya adalah najis. Hal ini mencakup benda yang biasa keluar seperti kencing dan tanji, dan benda yang jarang keluar seperti darah dan nanah."},{"k":"fq","h":42,"t":"anjing, babi dan peranakan keduanya atau salah satunya hasil perkawinan dengan binatang yang suci."},{"k":"fq","h":42,"t":"Dengan bahasa \"benda cair\", mengecualikan ulat dan setiap benda padat yang tidak diproses oleh lambung, maka hukumnya tidak najis, akan tetapi terkena najis yang bisa suci dengan dibasuh."},{"k":"fq","h":42,"t":"Dalam sebagian redaksi diungkapkan dengan bahasa \"setiap perkara yang akan keluar\" dengan menggunakan lafadz fi’il mudlari’ dan membuang lafadz \"ma’i’ (benda cair)."},{"k":"fq","h":42,"t":"Cara Mensucikan Najis Membasuh semua jenis air kencing dan kotoran walaupun keduanya dari binatang yang halal dimakan dagingnya, hukumnya adalah wajib."},{"k":"fq","h":42,"t":"Cara membasuh najis jika terlihat oleh mata dan ini disebut dengan \"najis ainiyah\" adalah dengan menghilangkan bendanya dan menghilangkan sifat- sifatnya, baik rasa, warna, atau baunya."},{"k":"fq","h":42,"t":"Jika rasanya najis masih ada, maka berbahaya. Atau yang masih tersisa adalah warna atau bau yang sulit dihilangkan, maka tidak masalah."},{"k":"fq","h":42,"t":"Jika najisnya tidak terlihat oleh mata dan ini disebut dengan \"najis hukmiyah\", maka cukup dengan mengalirnya air pada tempat yang terkena najis tersebut, walaupun hanya satu kali aliran."},{"k":"fq","h":42,"t":"Najis Mukhafafah Kemudian dengan bahasa \"jenisnya air kencing\", mushannif mengecualikan perkataan beliau yang berbunyi, \"kecuali air kencingnya anak kecil laki-laki yang belum pernah memakan makanan, maksudnya belum pernah mengkonsumsi makanan dan minuman untuk penguat badan. Maka sesungguhnya air kencing anak laki-laki tersebut sudah bisa suci dengan hanya memercikkan air padanya."},{"k":"fq","h":42,"t":"Dalam memercikkan air, tidak disyaratkan harus sampai mengalir."},{"k":"fq","h":43,"t":"Jika anak kecil laki-laki tersebut telah mengkonsumsi makanan untuk penguat badan, maka air kencingnya harus dibasuh secara pasti."},{"k":"fq","h":43,"t":"Dengan bahasa \"anak laki-laki\", mengecualikan anak kecil perempuan dan huntsa, maka air kencing keduanya harus dibasuh."},{"k":"fq","h":43,"t":"Di dalam membasuh barang yang terkena najis, disyaratkan airnya yang didatangkan/dialirkan pada barang tersebut jika airnya sedikit. Jika dibalik, maka barang tersebut tidak suci."},{"k":"fq","h":43,"t":"Sedangkan jika air yang banyak, maka tidak ada bedanya antara barang yang terkena najis yang datang atau didatangi air."},{"k":"fq","h":43,"t":"Najis Ma’fu Tidak ada najis yang dima’fu kecuali darah dan nanah yang sedikit. Maka keduanya dima’fu di pakaian dan badan, dan sholat yang dilakukan tetap sah walaupun membawa keduanya."},{"k":"fq","h":43,"t":"Dan kecuali bangkai binatang yang tidak memiliki darah yang mengalir seperti lalat dan semut, ketika binatang tersebut masuk ke dalam wadah air dan mati di sana. Maka sesungguhnya bangkai binatang tersebut tidak menajiskan wadah air yang dimasukinya."},{"k":"fq","h":43,"t":"Dalam sebagian redaksi menggunakan bahasa \"ketika mati di dalam wadah\"."},{"k":"fq","h":43,"t":"Perkataan mushannif \"terjatuh sendiri\", memberi pemahaman bahwa sesungguhnya seandainya bangkai binatang yang tidak memiliki darah mengalir itu dimasukkan ke dalam benda cair, maka berbahaya (menajiskan). Imam ar Rafi’i mantap dengan pendapat ini di dalam kitab asy Syarh ash Shaghir, namun beliau tidak menyinggung masalah ini di dalam kitab asy Syarh al Kabir."},{"k":"fq","h":43,"t":"Ketika bangkai binatang yang tidak memiliki darah mengalir itu berjumlah banyak dan merubah sifat cairan yang dimasukinya, maka bangkai itu menajiskan benda"},{"k":"fq","h":44,"t":"cair tersebut. Ketika bangkai ini muncul dari benda cair seperti ulatnya cukak dan buah-buahan, maka tidak menajiskan cairan tersebut secara pasti."},{"k":"fq","h":44,"t":"Di samping apa yang telah dijelaskan oleh mushannif, masih ada beberapa permasalahan yang dikecualikan yang disebutkan di dalam kitab-kitab yang diperluas keterangannya, sebagiannya telah dijelaskan di dalam \"Kitab Thaharah\"."},{"k":"fq","h":44,"t":"Najis Mughaladhah Semua binatang hukumnya suci kecuali anjing, babi, dan peranakan keduanya atau salah satunya hasil perkawinan dengan binatang yang suci."},{"k":"fq","h":44,"t":"Ungkapan mushannif ini mencakup terhadap sucinya ulat yang muncul dari najis, dan memang demikinlah hukumnya."},{"k":"fq","h":44,"t":"Bangkai, semuanya hukumnya adalah najis kecuali bangkai ikan, belalang dan anak Adam. Dalam sebagian redaksi diungkapkan dengan bahasa \"ibn Adam\", maksudnya bangkai masing-masing barang di atas, maka sesungguhnya hukumnya suci."},{"k":"fq","h":44,"t":"Wadah yang terkena liur anjing atau babi, maka harus dibasuh tujuh kali dengan menggunakan air suci mensucikan, salah satu basuhan dicampur dengan debu suci mensucikan yang merata ke seluruh tempat yang terkena najis."},{"k":"fq","h":44,"t":"Jika barang yang terkena najis tersebut dibasuh dengan air mengalir yang keruh, maka cukup mengalirnya air tersebut tujuh kali tanpa harus dicampur dengan debu."},{"k":"fq","h":44,"t":"Ketika benda najis anjing tersebut belum hilang kecuali dengan enam basuhan semisal, maka seluruh basuhan dianggap satu kali basuhan."},{"k":"fq","h":44,"t":"Tanah yang berdebu -yang terkena najis ini- tidak wajib diberi debu -saat membasuhnya- menurut qaul al ashah."},{"k":"fq","h":45,"t":"Untuk najis-najis yang lain, maka cukup dibasuh satu kali yang di alirkan pada najis tersebut. Dalam sebagian redaksi menggunakan bahasa \"marratan (sekali)\". Tiga kali (ats tsalatsu) basuhan adalah lebih utama. Dalam sebagian redaksi menggunakan bahasa \"ats tsalatsatu\" dengan menggunakan ta’ diakhirnya."},{"k":"fq","h":45,"t":"Air Sisa Basuhan Najis Ketahuilah sesungguhnya air basuhan najis setelah sucinya tempat yang dibasuh, hukumnya adalah suci, jika air tersebut terpisah dari tempat yang dibasuh dalam keadaan tidak berubah dan tidak bertambah ukurannya dari kadar ukuran sebelumnya besertaan menghitung kadar air yang diserap oleh tempat yang dibasuh."},{"k":"fq","h":45,"t":"Hal ini jika air basuhan tersebut tidak mencapai dua qullah. Jika mencapai dua qullah, maka syaratnya adalah tidak berubah."},{"k":"fq","h":45,"t":"Khamer Menjadi Cuka Setelah mushannif selesai menjelaskan najis yang bisa suci dengan dibasuh, maka beliau berlanjut menjelaskan najis yang suci dengan istihalah, yaitu perubahan sesuatu dari satu sifat ke sifat yang lain. Beliau berkata,"},{"k":"fq","h":45,"t":"Ketika khamer telah menjadi cuka dengan sendirinya, maka hukumnya suci. Khamer adalah minuman yang terbuat dari air perasan anggur. Baik khamer tersebut dimuliakan ataupun tidak. Makna takhallalat adalah khamer menjadi cuka."},{"k":"fq","h":45,"t":"Begitu juga hukumnya suci, seandainya ada khamer yang berubah menjadi cuka sebab dipindah dari tempat yang terkena matahari ke tempat yang teduh dan sebaliknya."},{"k":"fq","h":45,"t":"Jika khamer berubah menjadi cuka tidak dengan sendirinya, bahkan menjadi cuka dengan memasukkan sesuatu ke dalamnya, maka khamer tersebut tidak suci."},{"k":"fq","h":46,"t":"Ketika khamer menjadi suci, maka wadahnya pun menjadi suci karena mengikut pada khamernya."},{"k":"rm","h":10,"t":"MASALAH DARAH HAIDL Definisi Haid. Haid menurut bahasa artinya ialah mengalir. Adapun menurut istilah Syara’, yang dinamakan haid ialah darah yang kebiasaan keluar dari farji (kemaluan) seorang wanita yang telah berusia sembilan tahun, bukan karena melahirkan, dalam keadaan sehat dan warnanya merah semu hitam menghanguskan (Fathul Qarib:10)."},{"k":"rm","h":10,"t":"Dasar Hukum Haid. Adapun dasar hukum Haid adalah firman Allah Subhanahu wa Ta‘ala dalam Alqur’an sebagai berikut: ) : .( “Mereka bertanya kepadamu tentang haid. Katakanlah: “Haid itu adalah kotoran.” Oleh karena itu hendaklah kamu menjauhkan diri dari wanita di waktu haid, dan janganlah kamu mendekati mereka, sebelum mereka suci. Apabila mereka telah suci, maka campurilah mereka itu di tempat yang di perintahkan Allah kepada mu> Sesungguhnya Allah menyukai orang-orang yang taubat,"},{"k":"rm","h":11,"t":"dan menyukai orang-orang yang mensucikan.” (QS. Al-Baqarah: 222). Dan hadist Rasulullah Sallallahu ‘Alaihi wa Sallam Sebagai berikut: ). .( “Sesungguhnya haid ini yang telah menetapkan Allah atas anak- anak putri Nabi Adam As.” (HR. Bukhari dan Muslim dari ‘Aisyah Ra.)."},{"k":"rm","h":11,"t":"Nama-Nama Haid. Penyebutan nama haid menurut ulama Fuqaha terdapat 15 nama adalah sebagai berikut: - - - - - - - - - - - - - - - . Binatang Yang Mengalami Haid. Adapun hayawan atau binatang yang mengalami haid adalah delapan macam, yaitu sebagai berikut:"},{"k":"rm","h":12,"t":"4. Binatang kelinci (Jawa: mermut)"},{"k":"rm","h":12,"t":"8. Binatang anjing. Akan tetapi selain orang wanita, binatang-binatang tersebut haidnya tidak tertentu (Bujairami ala Al Khatib: 1/300). Tanda-Tanda Balig Bagi Wanita. Tanda-tanda balig bagi seorang anak wanita terdapat lima macam. Apabila salah satu dari lima perkara terdapat padanya, maka dihukumi sudah balig, ialah sebagai berikut:"},{"k":"rm","h":12,"t":"1. Sudah sampai umur 15 tahun Qamariyah (penanggalan bulan)."},{"k":"rm","h":12,"t":"2. Keluar air mani dari kemaluan setelah umur 9 tahun Qamariyah."},{"k":"rm","h":12,"t":"3. Keluar darah Haid setelah umur 9 tahun Qamariyah Taqriban, ya-itu kira- kira atau kurang sedikit dari 15 hari, walaupun hanya sebentar (Kasyifatu al Syaja: 16)."},{"k":"rm","h":12,"t":"4. Keluar bulu kemaluan setelah umur 9 tahun Qamariyah (Tabyinal Ishlah: 157)."},{"k":"rm","h":12,"t":"5. Dan kedua buah dadanya sudah menonjol ke depan secara jelas (Bidayatul Ummat: ) Tanda-Tanda Balig Bagi Lelaki. Adapun tanda-tanda balig bagi seorang anak lelaki sebanyak empat perkara. Apabila didapati pada seorang anak lelaki salah satu dari empat perkara, maka anak tersebut dihukumi sudah berumur balig, yaitu sebagai berikut:"},{"k":"rm","h":12,"t":"1. Sudah sampai umur 15 tahun Qamariyah (penanggalan bulan)."},{"k":"rm","h":13,"t":"2. Keluar air mani dari kemaluan setelah umur 9 tahun Qamariyah."},{"k":"rm","h":13,"t":"3. Keluar bulu kemaluan setelah umur 9 tahun Qamariyah. (Tabyinal Ishlah: 157). Permulaan Haid Bagi Wanita. Usia paling muda waktu keluar darah haid bagi seorang anak wanita, ialah berumur 9 tahun Qamariyah Taqriban (kira-kira). Adapun pengertian taqriban atau kira-kira ialah, apabila seorang anak wanita yang cukup umur 9 tahun kurang 16 hari dan malamnya ke atas (waktu yang cukup digunakan paling sedikitnya haid dan paling sedikitnya suci), mengeluarkan darah, maka tidak dihukumi haid, tetapi dihukumi darah istihadlah atau darah rusak (Fathul Qarib pada Hamisy Al Bajuri:1/112 dan Abyanal Hawaij: 11/268) Adapun pada waktu mengeluarkan darah seorang wanita, sudah berusia 9 tahun kurang dibawahnya 16 hari dan malam (waktu yang tidak cukup untuk paling sedikitnya haid serta paling sedikitnya suci) maka dihukumi darah haid."},{"k":"rm","h":13,"t":"Apabila seorang wanita mengeluarkan darah beberapa hari yang sebagian sebelum waktunya bisa haid, dan yang sebagian lagi setelah waktunya bisa haid, maka darah yang pertama dihukumi darah istiha-dlah, dan darah yang akhir dihukumi darah haid."},{"k":"rm","h":13,"t":"Suatu Contoh. Sorang anak wanita cukupnya umur 9 tahun masih kurang 20 hari dan malam, lalu ia mengeluarkan darah lagi lamanya 10 hari dan malam, maka darah yang pertama selama 4 hari dan malam lebih sedi-kit, dihukumi darah istihadlah, karena kurangnya dari cukup umur 9 tahun masih cukup untuk haid serta suci."},{"k":"rm","h":13,"t":"Adapun darah yang tertinggal, yang lamanya 6 hari dan malam, kurang sedikit, dihukumi darah haid, karena kurangnya dari cukup u-mur 9 tahun sudah tidak cukup untuk haid serta suci (Hasyiyah al-Jamal ala Syarhi al- Minhaj: 1/236)."},{"k":"rm","h":14,"t":"Lamanya Waktu Haid dan Sucinya. Seorang wanita mengeluarkan darah yang dihukumi haid adalah sekurang-kurangnya masa sehari semalam atau 24 jam, baik selama 24 jam itu darah keluar terus menerus, atau terputus-putus selama 15 hari dan malam. Yakni suatu tempo keluar darah di tempo lain putus darah, yang seandainya mengeluarkan darahnya itu terjumlah cukup 24 jam, hal ini dihukumi darah haid, asalkan semuanya itu masih didalam 15 hari dan malam."},{"k":"rm","h":14,"t":"Sehingga, apabila darah yang keluar jumlahnya tidak cukup 24 jam, tidaklah dihukumi darah haid, melainkan dihukumi darah istiha-dlat (Minhaju al-Qawim: 29 dan Abyanal Hawaij: 11/268)."},{"k":"rm","h":14,"t":"Bahwa yang dimaksud dengan bil ittishal atau terus menerus yaitu seumpama kapuk kapas dimasukkan ke dalam kemaluan wanita, masih adanya darah itu, masih dihukumi mengeluarkan darah, sekalipun darah tidak sampai ke luar ke tempat yang wajib dibasuh ketika istinja’ (ber-suci). Hasyiyah Al Turmusi ala al Minhaju al-Qawim: 1/538)."},{"k":"rm","h":14,"t":"Adapun sebanyak-banyaknya seorang wanita mengeluarkan darah haid adalah 15 hari dan 15 malam. Pada kebiasaanya, mengeluarkan darah haid selama 6 atau 7 hari dan malam. Semuanya ini berdasarkan hasil penelitian Imam Syafi’i Ra kepada wanita Arab di Timut Tengah. Adapun paling lamanya seorang wanita mengeluarkan darah haid adalah 15 hari dan malam (Al Minhaju al-Qawim: 29)."},{"k":"rm","h":14,"t":"Dan sekurang-kurangnya suci yang memisahkan antara satu haid dengan haid yang lain ialah 15 hari dan 15 malam. Adapaun sebanyak-banyaknya suci tidak ada batasnya, bahkan kadang sudah tidak keluar darah haid lagi, karena usia atau keadaan. Dan pada kebiasaannya suci tersebut meliha kepada kebiasaannya haid. Apabila haidnya enam hari, maka sucinya adalah 24 hari, dan apabila haidnya itu tujuh hari, maka sucinya adalah 23 hari (Qutu al- Habib: 44)."},{"k":"rm","h":14,"t":"Masalah-Masalah. Darah yang keluar dari kemaluan seorang wanita yang sedang ha-mil adalah termasuk darah haid, apabila lamanya sehari semalam serta tidak lebih dari 15 hari dan malamnya, dan mengeluarkan darah tersebut sebelum melahirkan anak (Fathul Wahhab: 1/27)."},{"k":"rm","h":14,"t":"Seorang wanita ketika mengeluarkan darah haid dengan terputus putus, semuanya dihukumi haid, baik ketika mengeluarkan darah atau ketika putus yang ada sela-selanya itu."},{"k":"rm","h":15,"t":"Ketahuilah!. Seorang wanita, sama saja Mubtadi’at (baru sekali mengeluarkan darah) atau Mu’tadat (yang sudah pernah haid dan suci), dihukumi haid (haram melaksanakan perkara yang diharamkan kepada orang yang haid), sebab hanya mengeluarkan darah). Kemudian kalau darah terse-but ternyata putus sebelum cukup sehari semalam, maka hukumnya bukan darah haid, sehingga ia diwajibkan mengqadla shalat yang di tinggalkan selama mengeluarkan darah tersebut. Dan apabila darah itu sampai cukup sehari semalam, maka tentunya dihukumi darah haid (Hasyiyah Al Syarqawi ‘ala al- Tahrir: 1/152)"},{"k":"rm","h":16,"t":"MASALAH DARAH NIFAS Definisi Nifas. Bahwa Nifas menurut bahasa berarti melahirkan. Adapun menu-rut istilah Syara’, Nifas ialah darah yang keluar dari kemaluan seorang wanita setelah melahirkan (wiladah), dan sebelum melampui 15 hari dan malam dari lahirnya anak. Permulaan nifas itu dimulai dari keluarnya darah, bukan dari keluarnya anak."},{"k":"rm","h":16,"t":"Darah yang keluar bersama bayi atau sebelum melahirkannya, tidak dihukumi darah nifas, tetapi termasuk darah istihadlat atau darah rusak (darah penyakit). (Fathul Qarib: 109, Bughiyatul Mustarsyidin: 22)."},{"k":"rm","h":16,"t":"Dasar Hukum Nifas. Masa kebiasaan seorang wanita atas keluarnya darah nifas adalah 40 hari, sebagaimana yang diriwayatkan dari Ummu Salamah, dimana ia berkata: )"},{"k":"rm","h":16,"t":".( “Pada masa Rasulullah Saw. Para wanita yang sedang menjalani masa nifas menahan diri selama empat puluh hari atau empat puluh malam.” (HR. Abu Da-wud dan Tirmidzi)."},{"k":"rm","h":16,"t":"Para ulama dari kalangan sahabat Rasulullah Saw. dan para tabi’in telah menempuh kesepakatan, bahwa wanita-wanita yang sedang men-jalani masa nifas harus meninggalkan shalat selama empat puluh hari. Apabila telah suci sebelum masa tersebut, maka hendaklah mandi dan mengerjakan shalat, demikian dikatakan oleh Imam Tirmidzi."},{"k":"rm","h":17,"t":"Lamanya Nifas dan Sucinya. Sekurang-kurangnya seorang wanita keluar darah nifas adalah satu tetesan, kebiasaannya Nifas 40 hari dan malam, sedang sebanyak-banyaknya nifas, selama 60 hari dan malam. Semuanya ini juga dengan dasar hasil penelitian Imam Syafi’i Ra. Kepa-da wanita Arab di Timur Tengah (Hasyiyah Al-Bajuri: 1/111 dan Abyanal Hawaij: 11/268)."},{"k":"rm","h":17,"t":"Paling lama nifas 60 hari tersebut, di hitung mulai dari keluarnya bayi. Adapun yang dihukumi darah nifas itu mulai dari keluarnya darah. Sehingga, seumpama seorang wanita melahirkan anak pada tanggal1 kemudian ketika mengeluarkan darah mulai tanggal 5 itu penuh 60 hari dan malamnya, dimulai tanggal 5, dan yang dihukumi darah nifas adalah mulai tanggal 5. Adapun waktu antara lahirnya bayi dengan keluarnya darah, dihukumi suci. Oleh karena itu ia tetap kewajiban shalat dan kewajiban kewajiban yang lain."},{"k":"rm","h":17,"t":"Masalah-Masalah. Batas antara lahirnya bayi dengan keluarnya darah nifas seorang wanita, paling lama 15 hari. Apabila jarak antara keduanya lebih dari 15 hari, maka tidak dihukumi darah nifas, tetapi dihukumi darah haid."},{"k":"rm","h":17,"t":"Apabila seorang wanita setelah melahirkan anak kemudian meng- eluarkan darah dengan terputus-putus (setelah putus lalu keluar lagi), yang masih dalam 60 hari dan terputus-putusnya darah tidak sampai 15 hari, maka semua darah yang dikeluarkan maupun putus-putus yang ada sela-selanya, darah tersebut dihukumi darah nifas (Hasyiyah Sulai-man al-Jamal ‘ala Syarhi al-Minhaj: 1/227)."},{"k":"rm","h":17,"t":"Contoh-Contoh: Seorang wanita melahirkan anak, kemudian langsung mengeluar-kan darah selama 15 hari, lalu putus selama 14 hari, lalu keluar darah lagi selama 10 hari, maka darah yang keluar serta putus di sela-selanya itu dihukumi nifas. Dan ia pada waktu berhenti tersebut diwajibkan mandi, shalat dan lain sebagainya seperti halnya orang yang suci, wala-upun akhirnya ternyata semuanya itu tidak sah, karena sebenarnya masih ada di dalam nifas. Darah yang kedua (darah keluar setelah berhenti) itu, mulai keluar darah setelah tenggang 60 hari dari lahirnya anak, maka darah yang pertama (darah sebelum berhenti) dihukumi da-rah nifas, darah kedua dihukumi darah haid dan berhentinya dihukumi keadaan suci."},{"k":"rm","h":17,"t":"Seorang wanita melahirkan anak, kemudian mengeluarkan darah selama 59 hari, lalu berhenti selama dua hari, kemudian mengeluarkan darah"},{"k":"rm","h":18,"t":"lagi selama tiga hari, maka darah yang pertama dihukumi nifas, darah yang kedua dihukumi haid dan berhentinya dihukumi suci yang memisah antara haid dan nifas."},{"k":"rm","h":18,"t":"Dan seumpama darah yang kedua masih ada di dalamnya 60 hari, tetapi berhentinya selama 15 hari, maka darah yang pertama juga dihu-kumi nifas, darah yang kedua dihukumi haid dan berhentinya juga di hukumi suci. Contohnya: Seorang wanita melahirkan anak, kemudian mengelu-arkan darah selama 10 hari, lalu berhenti selama 16 hari, kemudian mengeluarkan darah lagi, selama 4 hari, maka darah yang pertama dihukumi nifas, darah yang kedua. dihukumi haid dan berhentinya dihukumi suci yang memisah antara haid dan nifas."},{"k":"rm","h":18,"t":"Peringatan!. Keadaan suci yang memisahkan antara haid dengan nifas, atau memisahkan antara nifas dengan nifas itu, tidak disyaratkan harus ada 15 hari 15 malam, melainkan bisa saja hanya sehari atau bahkan kurang dari satu hari. Berbeda dengan keadaan suci yang memisah antara haid dengan haid. Contoh keadaan waktu suci yang memisahkan antara haid dengan nifas ialah:"},{"k":"rm","h":18,"t":"1. Seorang wanita hamil mengeluarkan darah 5 hari, kemudian berhenti sehari, lalu ia melahirkan anak, kemudian mengeluarkan darah selama 40 hari, maka darah yang sebelum melahirkan dihukumi haid, dan darah yang sesudah melahirkan dihukumi nifas. Jadi waktu suci yang memisahkan antara haid dan nifas hanya sehari."},{"k":"rm","h":18,"t":"2. Seorang wanita melahirkan anak, kemudian mengeluarkan darah selama 60 hari, kemudian berhenti sehari, lalu keluar darah lagi selama 10 hari, maka darah yang sebelum berhenti dihukumi nifas, dan darah keluar yang setelah berhenti dihukumi haid. Jadi waktunya suci yang memisahkannya hanya sehari."},{"k":"rm","h":18,"t":"3. Waktu keadaan suci yang memisahkan antara nifas dengan nifas: Se-orang wanita melahirkan anak, kemudian disetubuhi oleh suaminya masih dalam keadaan nifas, dan akhirnya wanita itu hamil lagi, lalu setelah selesainya nifas cukup 60 hari, darahnya berhenti selama sehari, lalu ia melahirkan berupa segumpal darah, kemudian nifas lagi, maka berhenti yang lamanya sehari itu dihukumi suci, yang memisahkan antara nifas dengan nifas (Minhaju al-Qawim dengan Hasyiyah Sulaiman Kurdi :1/131, Syarhu al- Mihaj serta Hasyiyah Sulaiman al-Jamal: 1/227)."},{"k":"rm","h":19,"t":"Aneka Macam Darah. Faidah untuk mengetahui hukum-hukum istihadlat yang akan dibicarakan, maka harus lebih dahulu mengetahui, bahwa darah itu ada yang kuat (warnanya tua) dan ada yang lemah (warnanya muda). Untuk mengetahui perbedaan antara darah yang kuat dengan darah yang le-mah, harus mengetahui warna-warnanya, rupa-rupa dan sifat-sifatnya darah. Warnanya sebanyak 5 macam ialah: ."},{"k":"rm","h":19,"t":"5. Darah keruh. Darah hitam lebih kuat dari pada darah merah, darah merah lebih kuat dari pada darah merah semu kuning, darah merah semu kuning lebih kuat dari pada darah kuning, darah kuning lebih kuat dari pada darah keruh (Fathul Wahhab pada Hamisy Sulaiman al-Jamal: 1/247)."},{"k":"rm","h":19,"t":"Sifat-Sifat Darah Adapun sifat-sifat darah sebanyak empat macam ialah:. 1. Darah kental dan bau busuk"},{"k":"rm","h":19,"t":"4. Darah tidak kental dan tidak bau busuk. Darah kental lebih kuat dari pada darah cair, darah berbau busuk lebih kuat dari pada darah yang tidak berbau busuk, darah hitam kental lebih kuat dari pada darah hitam tidak kental, dan darah kental berbau busuk lebih kuat dari pada darah kental saja. atau berbau busuk saja (Fathul Wahhab pada Hamisy Sulaiman al-Jamal: 1/247)."},{"k":"rm","h":20,"t":"Apabila seorang wanita mengeluarkan darah dua yang sama sifat-nya, maka didahulukan darah yang keluar pertama, seperti darah hitam cair dan merah kental, darah hitam kental dan merah kental berbau dan seperti darah merah berbau busuk dan darah hitam tidak berbau busuk."},{"k":"rm","h":20,"t":"Dan apabila sebagian darah mempunyai sifat yang menyebabkan kuat, dan sebagian lagi juga mempunyai sifat yang menyebabkan kuat, maka yang dihukumi darah kuat ialah darah yang lebih banyak sifat-sifatnya yang menyebabkan kuat."},{"k":"rm","h":20,"t":"Contoh-Contoh. Pertama, Darah hitam, kental dan berbau busuk lebih kuat dari pada darah hitam, kental dan tidak berbau, dan lebih kuat dari pada darah hitam, cair dan berbau busuk, dan lebih kuat dari pada darah merah, kental dan berbau busuk, karena darah yang nomor pertama (hitam, kental dan berbau busuk) adalah mempunyai sifat yang menye-babkan kuat jumlahnya ada tiga yaitu (1) Rupa atau warna (2) Kental (3)Berbau."},{"k":"rm","h":20,"t":"Adapun darah yang kedua, ketiga dan keempat, hanyalah mempu-nyai sifat yang menyebabkan kuat karena jumlahnya ada dua macam. Kedua, Darah merah, kental dan berbau busuk adalah lebih kuat dari pada darah hitam, cair dan tidak berbau busuk, lebih kuat dari pada merah, kental dan tidak berbau busuk, lebih kuat dari pada darah merah, cair dan berbau busuk, karena darah yang pertama (darah merah, kental dan berbau busuk) itu mempunyai sifat yang menyebab-kan kuat jumlahnya, karena ada dua macam."},{"k":"rm","h":20,"t":"Ketiga, Darah merah semu kuning, kental dan berbau busuk itu lebih kuat dari pada darah merah, cair dan tidak berbau busuk. Lebih kuat dari pada darah merah semu kuning, kental dan tidak berbau bu-suk, lebih kuat dari pada darah merah semu kuning, cair dan berbau busuk, karena darah yang pertama (darah merah semu kuning, kental dan berbau busuk itu mempunyai sifat yang menyebabkan hitungannya berjumlah dua."},{"k":"rm","h":20,"t":"Adapun darah yang kedua, ketiga dan keempat hanya mempunyai sifat yang menyebabkan kuat jumlahnya hanya satu. Keempat, darah hitam, cair dan berbau busuk itu lebih kuat dari pada darah merah, kental dan tidak berbau busuk, lebih kuat dari pada darah merah, cair dan berbau busuk, karena darah yang pertama itu mempunyai sifat yang menyebabkan kuat cacahnya dua. Adapun darah selanjutnya, hanya mempunyai sifat yang menyebabkan kuat, jumlahnya satu."},{"k":"rm","h":21,"t":"Kelima, Darah hitam, cair dan tidak berbau busuk itu lebih kuat dari pada darah merah, cair dan tidak berbau, darah merah, kental dan tidak berbau busuk, darah kuning, cair dan berbau busuk lebih kuat dari pada darah kuninga, cair dan tidak berbau busuk, karena tiap-tiqap darah yang pertama itu mempunyai satu sifat yang menyebabkan kuat. Adapun tiap-tiap darah yang kedua, tidak mempunyai sifat yang menye-babkan kuat sama sekali. Apabila cacahnya sifat yang menyebabkan kuat, yang dimiliki sebagian darah yang lain, maka yang dihukumi kuat adalah darah yang pertama kali keluarnya, seperti contoh di bawah ini: Pertama, Darah merah, kental dan berbau busuk dengan darah hitam, kental dan tidak berbau busuk, atau dengan darah hitam, cair dan berbau busuk, maka yang dihukumi kuat adalah darah yang per-tama keluarnya, karena sifat yang menyebabkan kuat yang dimiliki itu jumlahnya sama keduanya."},{"k":"rm","h":21,"t":"Kedua, Darah merah, cair dan tidak berbau busuk, dengan darah merah semu kuning, cair dan berbau busuk, maka yang dihukumi kuat ialah darah yang lebih dulu keluarnya, karena sifat yang menyebabkan kuat yang dimiliki itu sama dengan salah satunya."},{"k":"rm","h":21,"t":"Peringatan!. Bahwa yang dikehendaki berupa lemah, hanya berupa lemah saja, tidak tercampur berupa kuat. Untuk itu apabila ada darah berupa lemah masih tercampur berupa kuat, itu termasuk golongan darah yang berupa kuat. Sebagai contoh: Darah merah terdapat garis-garis hitam itu di hukumi darah hitam, dan darah merah semu kuning terdapat garis-garisnya merah, itu dihukumi darah merah, demikian dan seterusnya (Tuhfah al-Muhtaj dengan Hasyiyah al-Syarwani: 1/402)."},{"k":"rm","h":22,"t":"MASALAH ISTIHADLAT Definisi Istihadlat. Istihadlat, menurut bahasa artinya mengalir. Adapun menurut istilah Syara’, Istihadlat ialah darah yang keluar dari kemaluan seorang wanita pada waktu selain waktunya haid dan nifas, dan bukan atas ja-lan sehat (Fathul Qarib pada Hamisy Al-Bajuri: 1/109)."},{"k":"rm","h":22,"t":"Seorang wanita yang mengeluarkan darah istihadlat dinamakan Mustahadlat.. Dasar Hukum Istihadlat. Masalah istihadlat ini adalah berdasarkan Hadits Nabi Muhammad Sallahu ‘Alaihi wa Sallam dari Ummu Salamah, yaitu: : ."},{"k":"rm","h":22,"t":") .( “Bahwa ia pernah meminta fatwa kepada Rasulullah Salla-llahu Alaihi wa Sallam mengenai seorang wanita yang selalu menge-luarkan"},{"k":"rm","h":23,"t":"darah. Maka Rasulullah bersabda: Hitunglah berdasarkan bilangan hari dan malam dari masa haid pada setiap bulan berlangsungnya, sebelum ia terkena serangan darah penyakit yang menimpanya itu. Maka tinggalkanlah shalat sebanyak bilangan haid yang biasa dijalani setiap bulan. Apabila ternyata melewati dari batas yang berlaku, maka hendaklah ia mandi, lalu memakai cawat (pembalut) dan mengerjakan shalat.” (HR.Abu Dawud dan An-Nasai dengan isnad hasan)."},{"k":"rm","h":23,"t":"Mustahadlat Ada Tujuh Macam. Menurut Syaikh Ibrahim Al Bajuri dalam kitab karangannya, Al Bajuri menerangkan, bahwa mustahadlat, yakni orang yang menge-luarkan darah istihadlat terdapat tujuh macam ialah:"},{"k":"rm","h":23,"t":"1. Mubtadi’at Mumayyizat Pertama, Mubtadi’at Mumayyizat: yaitu seorang wanita yang baru saja mengeluarkan darah haid pertama dan ia mampu membeda-beda kan darah yang dikeluarkan diantara darah kuat (tua) dengan darah le-mah(muda). Adapun darah yang lemah dinamakan istihadlat dan darah yang kuat dinamakan haid. Apakah darah yang kuat itu keluar lebih dulu, atau terakhir atau di tengah, selama tidak silih berganti."},{"k":"rm","h":23,"t":"Mubtadi’at Mumayyizat dapat dihukumi seperti di atas, apabila menepati syarat-syarat empat perkara sebagai berikut:"},{"k":"rm","h":23,"t":"1. Darah kuat tidak lebih dari masa sehari semalam."},{"k":"rm","h":23,"t":"2. Darah kuat tidak lebih dari 15 hari dan 15 malam."},{"k":"rm","h":23,"t":"3. Darah yang lemah tidak kurang dari 15 hari dan 15 malam."},{"k":"rm","h":23,"t":"4. Antara darah kuat dengan darah lemah harus tidak silih berganti. Apabila syarat empat perkara tersebut tidak cukup, maka ia terma suk golongan Mubtadi’at Ghairu Mumayizat, sebagaimana yang akan diterangkan. Bagi Mubtadi’at Mumayyizat pada bulan pertama dalam melaksa-nakan mandi harus menunggu penuhnya 15 hari dan 15 malam. Dan ia kewajiban mengqadla shalat yang ditinggalkan, selama mengeluarkan darah lemah. Pada bulan kedua dan seterusnya, ia dalam melaksanakan mandi sewaktu-waktu"},{"k":"rm","h":24,"t":"darah kuat yang keluar sudah berganti dengan darah lemah. Pada bulan itu ia tidak mempunyai hutang shalat. Contoh-Contoh. 1. Seorang wanita mengeluarkan darah kuat selama tiga hari, lalu mengeluarkan darah lemah 27 hari, maka yang tiga hari pertama dihukumi darah haid, dan yang 27 hari terakhir dihukumi darah istihadlat."},{"k":"rm","h":24,"t":"2. Seorang wanita mengeluarkan darah kuat tujuh hari, lalu menge-luarkan darah lemah sembilan hari, maka tujuh hari yang pertama dihukumi darah haid dan yang sembilan hari dihukumi darah istihadlat."},{"k":"rm","h":24,"t":"3. Seorang wanita mengeluarkan darah lemah selama 11 hari, lalu mengeluarkan darah kuat 12 hari,maka 11 hari yang pertama di-hukumi darah istihadlat, sedangkan 12 hari yang akhir dihukumi darah haid."},{"k":"rm","h":24,"t":"4. Seorang wanita mengeluarkan darah lemah selama lima hari, lalu mengeluarkan darah kuat selama enam hari, kemudian keluar lagi darah lemah selama 19 hari, maka darah lima hari yang pertama dihukumi darah istihadlat, enam hari yang di tengah-tengah di hukumi darah haid dan 19 hari yang terakhir dihukumi darah istihadlat lagi (Syarah al-Tahrir dengan Hasyiyah al-Syarqawi: 1/153, Hasyiyah Syarwani ala al-Tuhfah: 1/402)."},{"k":"rm","h":24,"t":"2. Mubtadi’at Ghairu Mumayyizat Kedua, Mubtadi’at Ghairu Mumayyizat, yakni seorang anak wanita yang baru haid pertama kali, dan tidak bisa membeda-bedakan darah yang dikeluarkan antara darah kuat dengan darah lemah, atau ia mam-pu membeda-bedakan darah yang dikeluarkan, tetapi tidak memenuhi syarat- syarat Mubtadi’at Mumayyizat yang jumlahnya ada empat macam seperti tersebut di atas."},{"k":"rm","h":24,"t":"Adapun hukumnya yang disebut haid hanya sehari semalam, dan masa sucinya adalah 29 hari dan malam untuk setiap bulannya sekira ia ingat waktu pertama mulai mengeluarkan darah. Namun apabila ia tidak ingat akan permulaannya mengeluarkan darah, maka ia termasuk golongan Mustahadlat Mutahayyirat (Mustahadlat yang kebingungan). Insya Allah hukumnya akan diterangkan di atas (Hasyiyah Al-Bajuri: 1/110)."},{"k":"rm","h":25,"t":"Bagi seseorang Mubtadi’at Ghairu Mumayyizat ini untuk bulan pertama dalam melaksanakan mandi, harus menunggu lengkapnya keluar darah 15 hari dan malam. Dan ia diwajibkan mengqadla shalat selama 14 hari dan malamnya. Untuk bulan kedua dan seterusnya, di-dalam melaksanakan mandi, ia tidak lagi perlu menunggu sampai leng-kapnya 15 hari dan malam, tetapi apabila darah sudah cukup sehari semalam, maka ia sudah kewajiban mandi. Pada bulan ini ia tidak mem-punyai hutang shalat (Hasyiyah al-Jamal ‘ala Syarhi al-Minhaj:1/249)."},{"k":"rm","h":25,"t":"Contoh-Contoh. Sebagai contoh-contoh dari masalah Mubtadi’at Ghairu Mumayyi-zat antara lain adalah sebagai berikut:"},{"k":"rm","h":25,"t":"1. Seorang wanita mengeluarkan darah selama satu bulan, yang semua sifat- sifatnya (kuat atau lemah) adalah sama, maka yang dihukumi darah haid hanya masa sehari semalam yang pertama. Adapun seterusnya dihukumi darah istihadlat."},{"k":"rm","h":25,"t":"2. Seorang wanita mengeluarkan darah selama empat bulan berturut turut, yang semua sifat-sifatnya adalah sama, maka yang dihukumi darah haid hanya empat hari dan malamnya, yaitu satu hari satu malam yang pertama. Sehari semalam tanggal 1 bulan kedua (31 harinya), sehari semalam tanggal 1 bulan ketiga (61 harinya), dan sehari semalam tanggal 1 bulan keempat (91 harinya). Adapun selain empat hari dan malamnya, semuanya itu dihukumi darah istihadlat."},{"k":"rm","h":25,"t":"3. Seorang wanita mengeluarkan darah selama 16 hari, yang segala sifatnya adalah sama, maka yang dihukumi darah haid hanyalah sehari semalam yang pertama. Adapun hari seterusnya dinamakan darah istihadlat."},{"k":"rm","h":25,"t":"4. Seorang wanita mengeluarkan darah selama 25 hari. Yang 23 jam darah kuat dan yang seterusnya darah lemah, maka yang dihukumi darah haid hanya sehari semalam yang pertama. Adapun hari yang seterusnya dinamakan darah istihadlat."},{"k":"rm","h":25,"t":"5. Seorang wanita mengeluarkan darah selama 25 hari. Yang 16 hari darah kuat dan yang seterusnya darah lemah, maka yang dihukumi darah haid hanyalah sehari semalam yang pertama. Sedangkan hari yang seterusnya dihukumi darah istihadlat."},{"k":"rm","h":25,"t":"6. Seorang wanita mengeluarkan darah selama 25 hari. Yang enam hari darah kuat, sedangkan yang 14 hari darah lemah, dan yang lima hari keluar darah kuat lagi, maka yang dihukumi darah haid hanyalah sehari semalam yang pertama. Adapun hari selanjutnya dinamakan darah istihadlat."},{"k":"rm","h":26,"t":"7. Seorang wanita mengeluarkan darah selama 25 hari. Sehari semalam keluar darah kuat dan sehari semalam keluar darah lemah, berselang seling seperti itu hingga sampai akhir, maka yang dihukumi darah haid hanyalah sehari semalam yang pertama. Sedang hari seterusnya dihukumi darah istihadlat."},{"k":"rm","h":26,"t":"3. Mu’taadat Mumayyizat Ketiga, Mu’tadat Mumayyizat, yakni seorang wanita yang sudah pernah haid dan pernah suci. Ia mampu membeda-bedakan darah yang dikeluarkan pada antara darah kuat dengan darah lemah. Hukumnya sama dengan Mubtadi’at Mumayyizat. Kecuali kalau antara lamanya ke-biasaan lamanya haid dengan perbedaannya darah ada tenggang selama 15 hari dan malamnya (waktu yang cukup untuk masa suci)."},{"k":"rm","h":26,"t":"Suatu Contoh: Pada kebiasaan wanita haid itu tiga hari, kemudian pada suatu bulan ia mengeluarkan darah 21 hari. Yang 19 hari darah lemah, sedang yang dua hari darah kuat, maka yang dihukumi darah haid lima hari. Tiga hari yang pertama, karena disamakan dengan kebiasaannya, dua hari yang terakhir, karena adanya perbedaan darah. Adapun 16 hari yang tengah-tengah, dihukumi darah istihadlat."},{"k":"rm","h":26,"t":"Peringatan!. Bahwa semua syarat-syarat Mubtadi’at Mumayyizat yang jumlah-nya empat perkara tersebut di atas merupakan syarat-syarat pula bagi Mu’tadat Mumayyizat (Al Minhaj serta Hasyiyah al-Jamal: 1/252)."},{"k":"rm","h":27,"t":"4. Mu’taadat Ghairu Mumayyizat Dzaakirat Li ‘Adaatiha…. Keempat, Mu’tadat Ghairu Mumayyizat Dzaakirat Li’adatiha Qadran wa Waqtan, yakni Seorang wanita yang sudah pernah haid dan pernah suci. Ia tidak mampu membeda-bedakan darah yang dikeluarkan antara darah yang kuat dengan darah yang lemah. Atau ia mampu membeda-bedakan darah yang dikeluarkannya, tetapi tidak memenuhi syarat-syarat Mubtadi’at Mumayyizat yang jumlahnya empat macam, yang juga menjadi syarat-syarat Mu’tadat Mumayyizat. Dan ia ingat pada lamanya permulaan keluar darah haid yang telah lalu."},{"k":"rm","h":27,"t":"Adapun hukumnya lama dan permulaan haid itu disamakan deng an kebiasaannya. Kebiasaan yang dapat digunakan untuk pedoman itu, cukup satu kali selama tidak berubah."},{"k":"rm","h":27,"t":"Contoh-Contoh. Seorang wanita pada bulan pertama haid lima hari mulai permu- laannya bulan, lalu suci selama 25 hari, kemudian ia mulai bulan yang kedua istihadlat dengan mengeluarkan darah yang tidak bisa dibedakan antara darah kuat dengan darah lemah, atau bisa dibeda-bedakan, tetapi tidak memenuhi syarat empat perkara, maka yang dihukumi haid ialah lima hari pertama. Dan yang dihukumi suci adalah 25 hari yang akhir untuk setiap bulannya seperti bulan pertama."},{"k":"rm","h":27,"t":"Apabila kebiasaannya berubah, maka harus disyaratkan dua putaran dengan urutan yang tetap serta teringat pada urutannya itu. Sebagai contoh dikemukakan: Seorang wanita pada bulan kesatu haid tiga hari, bulan kedua haid lima hari, bulan ketiga haidl tujuh hari, bulan keempat haid tiga hari, bulan kelima haid lima hari, pada bulan keenam haid tujuh hari. Lalu mulai bulan ketujuh ia istihadlat sampai beberapa bulan dengan mengeluarkan darah yang semua sifatnya sama, atau yang dibeda-bedakan antara darah kuat dengan darah lemah, tetapi tidak cukup syarat empat perkara, dan ia teringat pada urutannya haid yang sudah lewat, maka bulan ketujuh yang dihukumi darah haid adalah tiga hari."},{"k":"rm","h":27,"t":"Bulan ke delapan yang dihukumi haid lima hari, bulan ke sembilan yang dihukumi haid tujuh hari, bulan ke sepuluh yang di hukumi haid tiga hari, bulan ke sebelas yang dihukumi haid hanya tiga hari dan bulan ke duabelas yang dihukumi haid tujuh hari. Dan untuk bulan- bulan selanjutnya tinggal menyamakan seperti halnya urutan yang sebagaimana tersebut di atas (Syarhu al-Tahrir serta Hasyiyah Al Syar-qawi: 1/155)."},{"k":"rm","h":28,"t":"Apabila urutannya tidak tetap serta teringat pada haid yang tepat sebelum istihadlat, maka haidnya disamakan dengan bulan yang tepat sebelum istihadlat. Contohnya: Seorang wanita, pada bulan ke satu haid tiga hari, bulan kedua haid lima hari, bulan ketiga haid tujuh hari, bulan keempat haid tujuh hari, bulan kelima haid tiga hari, bulan enam haid lima hari, lalu mulai bulan ketujuh ia istihadlat sampai beberapa bulan dengan mengeluarkan darah yang semua sifatnya adalah sama. Atau dapat dibeda- bedakan, tetapi tidak memenuhi empat syarat di atas, serta ia teringat lamanya haid yang tepat sebelum istihadlat, maka yang dihukumi haid selama lima hari untuk setiap bulannya. Akan tetapi apabila tidak sampai dua kali putaran serta teringat pada haid yang tepat sebelum istihadlat, maka haidnya juga disamakan dengan bulan yang tepat sebelum istihadlat."},{"k":"rm","h":28,"t":"Contoh lain: Seorang wanita pada bulan kesatu haid tiga hari, bulan kedua haid lima hari, bulan ketiga haid tujuh hari. Kemudian mulai bulan keempat ia mengeluarkan darah istihadlat sampai beberapa bulan ke depan dengan mengeluarkan darah yang semua sifatnya adalah sama. Atau dapat dibeda-bedakan antara darah kuat dengan darah lemah, tetapi tidak memenuhi syarat-syarat yang empat perkara, dan ia teringat lamanya haid yang tepat sebelum istihadlat, maka yang dihukumi haid ialah tujuh hari untuk tiap-tiap bulannya."},{"k":"rm","h":28,"t":"Apabila urutannya tetap, akan tetapi ia lupa sebenarnya bilangan lamanya haid untuk setiap bulannya, maka ia kewajiban mandi pada setiap akhir hitungan haid yang sudah lewat."},{"k":"rm","h":28,"t":"Contoh lagi: Seorang wanita pada bulan kesatu haid tujuh hari, bulan kedua haid lima hari, bulan ketiga haid tiga hari, bulan ke empat haid tujuh hari, bulan ke lima haid lima hari, bulan ke enam haid tiga hari."},{"k":"rm","h":28,"t":"Kemudian mulai bulan ke tujuh, ia istihadlat hingga beberapa bu-lan dengan mengeluarkan darah yang semua sifatnya adalah sama, atau dapat dibeda- bedakan antara darah kuat dengan darah lemah, tetapi tidak memenuhi syarat-syarat empat macam, dan dia lupa akan benar-nya bilangan lamanya haid untuk bulan pertama serta bulan-bulan se-terusnya, apakah benar yang tiga hari atau lima hari, atau apakah yang tujuh hari, maka ia setiap bulannya kewajiban mandi tiga kali, yaitu akhirnya hari yang ketiga, akhirnya hari yang kelima dan akhirnya hari yang ketujuh."},{"k":"rm","h":28,"t":"Ia pada waktu antara mandi pertama dengan mandi paling akhir, kewajiban hati-hati, yakni kewajibkan shalat fardlu dan kewajiban lainnya, seperti orang yang keadaan suci. Dan diharamkan bersetubuh, membaca al-Qur’an dan lainnya seperti halnya wanita yang sedang haid."},{"k":"rm","h":28,"t":"Manakala urutannya tidak tetap dan si wanita itu terlupa sebenar-nya bilangan lamanya haid bulan yang tepat sebelun istihadlat, maka ia diwajibkan mandi juga setiap akhir bilangan lamanya haid yang sudah lewat. Contohnya:"},{"k":"rm","h":29,"t":"Seorang wanita pada bulan kesatu mengeluarkan darah haid tiga hari, bulan kedua haid lima hari, bulan ketiga haid tujuh hari, bulan keempat haid tujuh hari, bulan kelima haid tiga hari, bulan keenam haid lima hari, lalu bulan ketujuh ia istihadlat hingga beberapa bulan dengan mengeluarkan darah yang semua sifatnya adalah sama. Atau mampu memisah-misahkan antara darah kuat dengan darah lemah, tetapi tidak mencukupi syarat empat macam itu. Ia terlupa kebenaran lamanya haid bulan yang tepat sebelum ia istihadlat, Apakah benar yang tiga hari, li-ma hari, apakah benar yang tujuh hari, maka ia setiap bulan wajib akan mandi tiga kali. Yaitu akhir hari ketiga, akhir hari kelima dan akhir hari ketujuh. Dan ia waktu diantara mandi pertama dengan mandi terakhir adalah diwajibkan berhati-hati dengan segala perintah dan segala larang an seperti tersebut di atas."},{"k":"rm","h":29,"t":"Apabila tidak sampai dua kali putaran, dan ia terlupa kebenar-annya bilangan lamanya haid bulan yang tepat sebelum istihadlat, maka ia juga diwajibkan mandi setiap akhir bilangan lamanya haid yang lewat. Contohnya: Seorang wanita pada bulan kesatu haid tiga hari, bulan kedua haid lima hari, bulan ketiga haid tujuh hari. Lalu mulai bulan keempat, ia istihadlat sampai beberapa bulan dengan mengeluarkan darah yang semua sifatnya adalah sama. Atau bisa dibeda-bedakan antara darah kuat dengan darah lemah, tetapi tidak memenuhi syarat yang empat macam itu."},{"k":"rm","h":29,"t":"Atau ia terlupa kebenaran bilangan lamanya haid bulan yang tepat sebelum istihadlat, Apakah benar yang tiga hari, lima hari atau yang tujuh hari. Maka iapun setiap bulannya diwajibkan mandi tiga kali, yaitu akhir hari yang ketiga, dan akhir hari yang kelima dan akhir hari yang ketujuh. Ia pada waktu antara mandi pertama dengan mandi tera-khir, diwajibkan berhati-hati sebagaimana tersebut di atas."},{"k":"rm","h":29,"t":"Bagi Mustahadlat Mu’tadat Ghairu Mumayyizat zakirat li’adatiha, Qadran wa Waqtan itu untuk bulan pertama istihadlat, caranya mandi harus menunggu lengkapnya keluar darah 15 hari dan malamnya. Ia di-wajibkan mengqadla shalat yang ditinggalkan setelah lengkap kebiasa-annya haid. Adapun untuk bulan kedua dan bulan-bulan seterusnya, didalam melaksanakan mandi tidak perlu lagi menunggu lengkapnya 15 hari dan malam. Tetapi sewaktu-waktu keluar darah sudah cukup kebiasaan haid, ia sudah kewajiban mandi. Untuk bulan ini, ia tidak mempunyai hutang shalat."},{"k":"rm","h":29,"t":"5. Mu’taadat Ghairu Mumayyizat Nasiyatat Li ‘Adaatiha… Kelima, Mu’tadat Ghairu Mumayyizat Nasiyat li’adatiha qadran wa Waqtan, Yakni: Seorang wanita yang sudah pernah haid dan pernah suci, ia"},{"k":"rm","h":30,"t":"tidak dapat membeda-bedakan darah yang dikeluarkan antara darah kuat dengan darah lemah. Atau dapat membeda-bedakan darah yang dikeluarkan, tetapi ia tidak mencukupi syarat-syarat Mubtadi’at Mumayyizat sebangak empat perkara, yang juga menjadi syarat Mu’tadat Mumayyizat, dan ia terlupa lamanya dan permulaannya keluar darah haid yang telah lewat. Orang wanita yang seperti itu, menurut istilah ulama Fiqih dina-makan Muhayyarat (orang wanita istihadlat yang kebingungan). Adapun hukumnya, ia senantiasa kewajiban berhati-hati. Yaitu senantiasa diha-ramkan bersetubuh, membaca al-Qur’an diluar shalat dan lain-lainnya, seperti orang yang haid. selalu diwajibkan shalat dan puasa Ramadlan seperti orang yang dalam keadaan suci. Apabila ia sama sekali tidak teringat waktu berhentinya darah haid yang telah lewat, maka ia diwa-jibkan mandi setelah masuk waktu untuk setiap mengerjakan shalat fardlu."},{"k":"rm","h":30,"t":"Akan tetapi, apabila ia teringat waktu berhenti, upamanya waktu terbenamnya matahari, maka ia diwajibkan mandi hanya setiap waktu terbenamnya matahari. Dan untuk waktu-waktu shalat yang lain cukup wudlu saja. Adapun caranya puasa Ramadlan, ia harus melaksanakan puasa satu bulan terus menerus, karena menyerupai sebenarnya mulai haid tanggal 1 siang, lalu haid 15 hari dan malam. Jadi berhenti haid tanggal 16 siang. Dan menyerupai sebenarnya mulai haid tanggal 2 siang dan berhentinya tanggal 17 siang. Dan menyerupai pula sebenarnya mulai haid tanggal 3 siang dan berhentinya pada tanggal 8 siang. Demikian seterusnya. Jadi setiap tanggal satu bulannya (30 hari) yang dapat dipastikan sah terdapat 14 hari. Jadi puasa dua bulan, apabila umurnya Ramadlan 30 hari, yang mesti sah ada 28 hari dan apabila umurnya Ramadlan hanya 29 hari, maka yang sah adalah 27 hari."},{"k":"rm","h":30,"t":"Selanjutnya ia masih mempunyai hutang puasa dua hari. Adapun cara mengqadla puasa dua hari ini, ia harus melaksanakan puasa tiga hari berturut- turut, lalu tidak puasa 12 hari berturut-turut, lalu puasa lagi tiga hari berturut-turut. Dengan cara seperti itu, puasanya yang sah sudah lengkap/cukup satu bulan (Hasyiyah Al-Bajuri: 1/111)."},{"k":"rm","h":30,"t":"Adapun cara mengqadla puasa sehari bagi Mustahadlat Mutaha-yyirat ialah wanita itu supaya mengejakan puasa tiga hari dengan cara: diantara hari ke 15 dengan hari puasa ketiga itu harus diberi tenggang waktu yang sama, atau lebih pendek daripada tenggang antara puasa ke satu dan puasa kedua (Syarah Al Minhaj pada Hamisy al-Jamal:1/257)."},{"k":"rm","h":31,"t":"6. Mu’taadat Ghairu Mumayyizat Dzakirat Lil Qadri Duunal Waqti Keenam, Mu’taadat Ghairu Mumayyizat Zaakirat lil Qadri duun al Wakti, yakni: Seorang wanita yang sudah pernah mengalami haid serta suci dan ia tidak mampu membeda-bedakan darah yang dikeluarkannya diantara darah kuat dengan darah lemah. Atau ia mampu membeda-bedakan darah yang dikeluarkannya, tetapi tidak mencukupi syarat-syarat Mubtadi’at Mumayyizat yang jumlahnya empat perkara, yang juga menjadi syarat-syarat Mu’taadat Mumayyizat. Dan ia hanya teringatnya pada kebiasaan lamanya haid dan terlupa kebiasaan mulainya (Hasyiyah Al Bajuri: 1/111)."},{"k":"rm","h":31,"t":"Suatu Contoh. Salah seorang wanita teringat bahwa haid dirinya selama lima hari menempati 10 hari pertama, namun terlupa mulainya bertepatan tanggal berapa, hanya ia teringat bahwa pada tanggal 1 ianya dalam keadaan suci, maka tangga 1 yakin suci, tanggal 2 sampai 5 kemungkinan haid kemungkinan suci, tanggal 6 yakin haid, tanggal 7 sampai 10 kemu-ngkinan haid dan kemungkinan pula suci, serta kemungkinan mulai berhenti haid, tanggal 11 sampai akhir bulan yakin suci."},{"k":"rm","h":31,"t":"Dasar ketentuan hukumnya ialah: Waktu yang yakin haid, seperti kebiasaannya haid (haram shalat dan lainnya), waktu yang yakin suci, seperti kebiasaannya suci (halal bersetubuh dan sebagainya)."},{"k":"rm","h":31,"t":"Adapun waktu yang kemungkinan haid dan kemungkinan suci adalah hukumnya sama dengan seorang wanita Mutahayyirat seperti yang telah disebutkan (kewajiban berhati-hati), kecuali melaksanakan kewajiban mandi, hanyalah waktu yang kemungkinan mulai berhentinya haid saja."},{"k":"rm","h":31,"t":"7. Mu’taadat Ghairu Mumayyizat Dzakirat Lil Waqti Duunal Qadri Ketujuh, Mu’taadat Ghairu Mumayyizat Zaakirat lil Waqti duunal Qadri, Yakni: Seorang wanita yang sudah pernah mengalami haid serta mengalami suci. Ia tidak bisa membeda-bedakan darah yang dikeluar-kan, antara darah kuat dengandarah lemah. Atau mampu membeda-bedakan darah"},{"k":"rm","h":32,"t":"yang dikeluarkan, tetapi tidak mencukupi syarat-syarat Mubtadi’at Mumayyizat yang jumlahnya empat macam, yang merupakan syarat-syarat Mu’tadat Mumayyizat. Dan ia hanya teringat pada kebia-saan mulainya haid, dan terlupa kebiasaan lamanya haid tersebut (Ha-syiyah Al Bajuri: 1/111)."},{"k":"rm","h":32,"t":"Suatu Contoh. Seorang wanita teringat bahwa mulainya haid pada tanggal 1, na-mun terlupa seberapa lamanya, maka tanggal 1 yakin haid, tanggal 2 sampai tanggal 15 kemungkinan haid dan kemungkinan suci dan kemungkinan mulai berhenti haid, tanggal 16 sampai akhir bulan yakin suci."},{"k":"rm","h":32,"t":"Adapun hukumnya waktu yang yakin haid, ya seperti kebiasaan haid. Waktu yang yakin suci, ya seperti kebiasaannya suci. Dan waktu yang kemungkinan memper haid serta memper suci dan memper mulai-nya berhenti haid adalah hukumnya sama dengan orang wanita Muta-hayyirat di atas."},{"k":"rm","h":32,"t":"Peringatan!. Pertama, Apabila ada seorang wanita mengeluarkan darah yang sifatnya tidak sama (sebagaian berupa darah kuat dan sebagian lagi darah lemah), tetapi lamanya tidak lebih dari 15 hari dan malam, maka semuanya itu dihukumi darah haid dan tidak boleh digolongkan dengan masalah istihadlat (yang baru saja dijelaskan), karena hukum perinci yang disampaikan dalam masalah istihadlat, hanya bagi wanita yang ketika mengeluarkan darah, lamanya lebih dari 15 hari dan malam (Ha-syiyah al Jamal ala Syarhi al Minhaj: 1/235)."},{"k":"rm","h":32,"t":"Kedua, Manakala seorang wanita mengeluarkan darah yang sudah memenuhi syarat-syaratnya haid, kemudian ia suci yang lamanya tidak sampai cukup 15 hari dan malamnya, lalu ia mengeluarkan darah lagi, maka darah yang pertama dihukumi darah haid dan darah kedua yang menjadi cukup 15 hari dan malam, dihukumi darah istihadlat, kemudi-an sisanya bila memenuhi syarat-syarat haid, maka dihukumi darah haid juga (Bughiyatul Mustarsyidin: 21)."},{"k":"rm","h":32,"t":"Contohnya: Seorang wanita mengeluarkan darah lamanya tujuh hari, kemudian suci lamanya 13 hari dan malam, lalu mengeluarkan darah lagi lamanya enam hari dan malam, maka darah yang pertama lamanya tujuh hari, semuanya dihukumi darah haid. Permulaan darah yang kedua, yang lamanya dua hari dua malam, dihukumi darah istihadlat. Sebagai pelengkap, paling sedikitnya suci dan sisa yang la-manya empat hari empat malam, dihukumi darah haid juga."},{"k":"rm","h":33,"t":"Ketiga, Apabila di dalam kitab fiqih dikatakan bahasa bulan secara mutlak, maka yang dikehendaki adalah penanggalan bulan (Qamariyah). Terkadang penuh 30 hari dan kadang hanya 29 hari, kecuali ada ditiga masalah, yaitu:"},{"k":"rm","h":33,"t":"1. Masalah Mubtadi’at Ghairu Mumayyizat"},{"k":"rm","h":33,"t":"3. Masalah paling sedikitnya kandungan yang lamanya hanya enam bulan, maka semua yang dikehendaki bulan yang cukup 30 hari (Hasyiyah al- Syarqawi: 1/154)."},{"k":"rm","h":33,"t":"Keempat, Apabila seorang wanita mengeluarkan darah nifas sela-ma lebih dari 6o hari dan malam, adalah sama denga seorang wanita yang mengeluarkan darah haid selama lebih dari 15 hari dan malamnya. Jadi perlu dirinci lebih dahulu, Apakah ia termasuk mubtadi’at fi al-Nifas (wanita yang baru pertama nifas) atau tergolong Mu’tadat (sudah pernah nifas). Apakah ia tergolong Mumayyizat (bisa membeda-bedakan darah kuat dengan darah lemah), apakah termasuk Ghairu Mumayyizat (tidak bisa membeda- bedakannya)."},{"k":"rm","h":33,"t":"Apabila ia tergolong Mubtadi’at Mumayyizat, atau Mu’tadat Muma- yizat, maka yang dihukumi nifas adalah darah yang kuat dengan syarat darah yang kuat tidak lebih dari 60 hari (Tuhfatul Muhtaj: 1/414)."},{"k":"rm","h":33,"t":"Contohnya: Seorang wanita setelah selesai melahirkan kemudian mengeluarkan darah selama 65 hari. Yang 50 hari berupa darah kuat dan yang 10 hari berupa darah lemah, maka darah yang lamanya 55 ha-ri pertama dihukumi darah nifas, dan yang 10 hari terakhir dihukumi darah istihadlat. Apabila ia tergolong Ghairu Mumayyizat, maka hukumnya perlu di perinci lagi, seperti di bawah ini ialah: Bila seorang wanita sudah pernah nifas serta sudah pernah haid, maka lamanya darah yang dihukumi nifas adalah disamakan dengan kebiasaannya nifas yang pernah dialami."},{"k":"rm","h":33,"t":"Kemudian darah yang sesudah nya, lamanya sama dengan kebiasaan suci dari haid, maka dihukumi istihadlat, kemudian darah yang sesudahnya, yang lamanya sama deng-an kebiasaan haid, maka dihukumi haid. Demikian seterusnya saling berganti antara istihadlat lamanya sama dengan kebiasaan suci dan haid lamanya sama dengan kebiasaan haid. Contohnya: Seorang wanita yang kebiasannya nifas selama 20 hari, kebiasaan haid tujuh hari, dan sucinya 23 hari, kemudian ia setelah melahirkan anak, mengeluarkan darah selama 80 hari, semua sifatnya, kuat dan lemah sama, maka darah yang selama 20 hari permulaan dihukumi darah nifas. Lalu yang 23 hari seterusnya dihukumi darah istihadlat. Lalu tujuh hari"},{"k":"rm","h":34,"t":"seterusnya dihukumi darah haid. Yang 23 hari kemudian dihukumi darah istihadlat lagi, dan kemudian tujuh hari seterusnya dihukumi darah haid lagi. Dan apabila ia sudah pernah nifas, tetapi belum pernah haid, maka lamanya darah yang dihukumi nifas, disamakan dengan kebiasa-annya nifas yang sudah dialami. Lalu darah yang setelah lamanya 29 hari dan malam, dihukumi darah istihadlat. Lalu darah yang setelah lamanya sehari semalam, dihukumi darah haid, begitu seterusnya saling bergantian antara istihadlat lamanya 29 hari dan malamnya, dan haid yang lamanya sehari semalam (Hasyiyah Al Syibramulisi ala al Nihayah: 1/358)."},{"k":"rm","h":34,"t":"Contohnya: Seorang wanita yang kebiasannya nifas 15 hari, Ia be-lum pernah mengeluarkan darah haid, kemudian ia setelah melahirkan anak, mengeluarkan darah selama 75 hari dan sifat-sifatnya adalah sama, maka darah yang lamanya 15 hari pertama, dihukumi darah nifas. Yang 29 hari terusannya dihukumi istihadlat. Yang sehari terusnya dihukumi darah haid. Dan yang 29 hari terusnya, dihukumi darah istihadlat, kemudian yang sehari terusnya dihukumi darah haid lagi."},{"k":"rm","h":34,"t":"Apabila ia sudah pernah haid tetapi masih nifas pertama, maka darah yang dihukumi nifas hanyalah setetes pertama, seterusnya darah yang lamanya sama dengan kebiasaan suci dari haid, dihukumi darah istihadlat. Darah yang lamanya sama dengan kebiasaan haid, dihukumi darah haid. Demikian seterusnya saling bergilir antara istihadlat lama-nya sama dengan kebiasaannya suci, dan haid lamanya sama dengan kebiasaannya haid. Contohnya: Seorang wanita yang kebiasaannya haid 10 hari dan sucinya selama 25 hari. Ia belum pernah mengeluarkan darah nifas."},{"k":"rm","h":34,"t":"Lalu setelah ia melahirkan anak, mengeluarkan darah selama 70 hari lebih sedikit dan sifat- sifatnya sama, maka darah yang dihukumi nifas hanya setetes pertama. Seterusnya darah darah yang 25 hari terus, di hukumi istihadlat. Lalu yang 10 hari terus, dihukumi darah haid. Lalu yang 25 hari terusnya dhukumi darah istihadlat pula. Dan yang 10 hari terusnya dihukumi darah haid pula. Apabila ia belum pernah haid dan masih baru nifas pertama, ma-ka darah yang dihukumi nifas itu hanya setetes permulaan. Lalu darah yang setelah itu, lamanya 29 hari dan malam dihukumi darah istihadlat lalu darah yang setelah itu, lamanya sehari semalam, dihukumi darah haid."},{"k":"rm","h":34,"t":"Demikian seterusnya saling berganti antara istihadlat lamanya 29 hari dan haid lamanya sehari semalam."},{"k":"rm","h":34,"t":"Contohnya: Seorang wanita yang belum pernah haid dan belum pernah nifas, lalu ia setelah melahirkan anak, mengeluarkan darah sela-ma 90 hari lebih sedikit, maka yang dihukumi darah nifas hanya setetes permulaan. lalu darah yang 29 hari seterusnya dihukumi darah istiha-dlat. Kemudian darah yang sehari semalam seterusnya dihukumi darah haid. Lalu yang 29 hari"},{"k":"rm","h":35,"t":"seterusnya lagi dihukumi darah istihadlat juga. Kemudian yang sehari semalam seterusnya dihukumi darah haid lagi. Lalu darah yang 29 hari seterusnya, dihukumi darah istihadlat, dan darah yang sehari semalam terusannya dihukumi darah haid lagi."},{"k":"rm","h":35,"t":"Suatu Faidah. Apabila seorang wanita, setelah melahirkan anak, lalu mengeluar-kan darah selama 60 hari. Setelah berhenti satu jam kemudian keluar lagi darah selama 15 hari, maka hal ini tidak boleh digolongkan pada masalah yang baru dibicarakan. Karena pisahnya berhenti (suci). Kecua-li darah yang selama 60 hari, sebelum berhenti, semuanya, dihukumi darah nifas. Darah yang 15 hari setelah berhenti, semuanya, dihukumi darah haid. Dan berhentinya selama satu jam, dihukumi masa suci yang memisah antara haid dengan nifas. Jadi tidak ada darah istihadlat da-lam masalah ini."},{"k":"rm","h":35,"t":"Kaifiyat Shalat Mustahadlat dan Beser. Bahwa istihadlat tidak sama hukumnya dengan haid atau nifas. Istihadlat itu termasuk bagian hadas kecil yang sifatnya terus-menerus seperti beser air seni atau beser air madzi. Maka mustahadlat tetap di-wajibkan shalat fardlu dan puasa Ramadlan, dan tidaklah diharamkan membaca al- Qur’an, bersetubuh dan lain-lain (Syarhu al-Minhaj pada Ha-misy Hasyiyah al Jamal: 1/242)."},{"k":"rm","h":35,"t":"Oleh karena Mustahadlat dan orang yang beser itu terus-menerus mengeluarkan hadas dan najis, maka ketika akan mendirikan shalat, ia hendaklah lebih dulu mensucikan kemaluannya lalu di sumbat dengan kapuk atau kain sekiranya tidak sakit dan ketika tidak mengerjakan puasa Ramadlan. Apabila darahnya masih terus mengalir keluar di permukaan sumbatan, maka ia diwajibkan membalut. Apabila karena banyaknya darah, hingga tetap keluar ke permukaan pembalut, maka dimaafkan. Dan apabila ia sedang mengerjakan puasa, hendaklah supaya membuat pembalut saja, karena menyumbat itu menyebabkan batal puasanya (Minhajul Qawim: 30, dan Fathul Wahab pada Hamisy Hasyiyah Al-Jamal: 1/242)."},{"k":"rm","h":35,"t":"Setelah dibalut, lalu wudlu dengan niat sepaya diperkenankan mengerjakan shalat fardlu. Bukan niat karena menghilangkan hadas atau niat bersuci dari hadas (Fathul Wahhab pada Hamisy Hasyiyah Sulaiman al- Jamal:1/105)."},{"k":"rm","h":35,"t":"Sejak mulai mensucikan kemaluan hingga wudlu, wajib dilakukan setiap akan mengerjakan shalat fardlu dan setelah masuk waktu shalat. Semua"},{"k":"rm","h":36,"t":"pekerjaan, mulai dari mensucikan kemaluan hingga shalat far-dlu, wajib dilaksanakan dengan segera. Maka apabila sesudah wudlu lalu berhenti lebih dulu, karena keperluan selain maslahatnya shalat, seperti makan, minum dan lain-lain, maka ia diwajibkan kembali mensucikan kemaluan dan seterusnya. Namun apabila berhentinya karena untuk kemaslahatan shalat, seperti menutup aurat, menjawab muadzin, me-nunggu jamaah, menunggu shalat Jum’at dan lain-lain, maka hal itu diperkenankan Syara’ (tidak perlu kembali bersuci lagi)."},{"k":"rm","h":36,"t":"Orang yang beser mani, ia diwajibkan mandi setiap akan menger-jakan shalat fardlu dengan niat supaya diperkenankan mengerjakan shalat fardlu. Tidak diperkenankan niat menghilangkan hadas atau niat bersuci dari hadas. Bagi orang yang hadasnya, seumpama untuk shalat, bisa dengan duduk, lalu hadasnya bisa berhenti, maka ia diwajibkan shalat dengan duduk. Nanti setelah sembuh tidak perlu mengqadla shalatnya (Minhaj al-Qawim: 30)."},{"k":"rm","h":36,"t":"Suatu Masalah. Bahwa wudlunya orang Da’aimul Hadats, yaitu orang yang terus- menerus berhadas, seperti orang yang beser dan mustahadlat, seluruh tubuhnya di syaratkan suci dari najis atau tidak? Jawabnya para ulama berbeda pendapat. Yang pertama mensyaratkan seleruh tubuh harus suci dari najis. Yang kedua, tidak mensyaratkan harus suci tubuhnya dari najis (Hasyiyah al-Jamal ala Syarhi al-Minhaj: 1/242)."},{"k":"rm","h":36,"t":"Peringatan!. Bagi seorang yang istihadlat dan orang beser, yang kebiasannya, pada akhir shalat ada berhentinya yang cukup untuk wudlu dan shalat, maka di dalam mengerjakan shalat wajib diakhirkan (Hasyiyah Al-Jamal ala Syarhi al- Minhaj: 1/245)."},{"k":"rm","h":36,"t":"Bagi orang yang beser, sah menjadi imam shalat, sekalipun, mak-mum tidak beser. Dan bagi orang istihadlat yang selain mutahayyirat, juga sah menjadi imam shalat, walaupun si makmum tidak istihadlat. Adapun orang istihadlat yang mutahayyirat tidak sah menjadi imam shalat, sekalipun makmumnya sama-sama mustahadlat mutahayyirat (Mughnil Muhtaj: 1/241)."},{"k":"rm","h":37,"t":"Perkara Yang Diharamkan Bagi Orang Haid dan Nifas Seorang wanita yang sedang haid atau nifas, diharamkan menger-jakan 11 perkara, yaitu sebagai berikut:"},{"k":"rm","h":37,"t":"1. Mengerjakan shalat fardlu maupun shalat sunnah,"},{"k":"rm","h":37,"t":"2. Mengerjakan thawaf di Baitullah Makkah, baik thawaf rukun, thawaf wajib atau thawaf sunnah."},{"k":"rm","h":37,"t":"3. Mengerjakan rukun-rukun khutbah Jum’at"},{"k":"rm","h":37,"t":"4. Menyentuh lembaran al-Qur’an Apalagi kitab al-Qur’an"},{"k":"rm","h":37,"t":"5. Membawa lembaran al-Qur’an. Apalagi kitab al-Qur’an."},{"k":"rm","h":37,"t":"6. Membaca ayat al-Qur’an, kecuali karena mengharap barakah, seperti membaca Bismillahirrahmaanirrahiim, memulai pekerjaan yang baik, Alhamdulilahi Rabbil ‘Alamiin, karena bersyukur dan Innaa Lillaahi wa Innaa Ilaihi Raaji’uun karena terkena musibah."},{"k":"rm","h":37,"t":"7. Berdiam diri di dalam masjid, sekiranya dikhawatikan darahnya tertetes didalamnya."},{"k":"rm","h":37,"t":"8. Mundar mandir didalam masjid, sekiranya dikahawatirkan darah-nya tertetes didalamnya."},{"k":"rm","h":37,"t":"9. Mengerjakan puasa Ramadlan, tetapi diwajibkan qadla. Adapun shalat tidak diwajibkan qadla."},{"k":"rm","h":37,"t":"10. Meminta cerai kepada suaminya, atau sebaliknya."},{"k":"rm","h":37,"t":"11. Melakukan Istimta’, bersenang-senang suami istri dengan pertemuan kulit antara pusar sampai dengan kedua lutut, baik bersyahwat atau tidak. Apalagi bersetubuh, meskipun kemaluannya lelaki di bungkus dengan kain, hukumnya jelas haram dosa besar."},{"k":"rm","h":37,"t":"Apabila haid atau nifas sudah berhenti, tetapi belum mandi, maka larangan 11 perkara ini tetap berlaku, kecuali puasa dan thalaq (Mahali serta Hasyiyah Al-Qalyubi: 1/100 dan Abyanal Hawaij: 11/269-270)."},{"k":"rm","h":38,"t":"Suatu Faidah. Dikatakan oleh ulama Fuqaha: bahwa suami yang menyetubuhi istrinya sebelum mandi, baik istrinya masih dalam keadaan haid atau sudah berhenti akan mengakibatkan terkena penyakit lepra (buduken: Jawa) terhadap anaknya (Hasyiyah Al-Qalyubi: 1/110)."},{"k":"rm","h":38,"t":"Seseorang yang haid atau nifas nanti setelah berhenti, diwajibkan mengqadla puasa Ramadlan yang ditinggalkan, dan tidak wajib mengqa-dla shalat fardlu secara Ijma’ dalam keduanya, karena kesukaran di dalam qadla shalat ank arena berulang-ulangnya shalat. Tidak demi-kian halnya qadla puasa (Al-Mihajul Qawim serta Hasyiyah Al-Turmu-si:1/548 dan Husnul Mathalib: 70)."},{"k":"rm","h":38,"t":"Hukum-hukum yang berpautan dengan haid, ada 20 perkara, 12 berupa hukum haram, yaitu:"},{"k":"rm","h":38,"t":"2. Melakukan sujud tilawah (bacaan dalam al-Qur’an), sujud syukur,"},{"k":"rm","h":38,"t":"3. Melakukan thawaf rukun, wajib, atau sunnah,"},{"k":"rm","h":38,"t":"4. Mengerjakan puasa wajib maupun sunnah,"},{"k":"rm","h":38,"t":"5. Melakukan I’tikaf di dalam masjid,"},{"k":"rm","h":38,"t":"6. Memasuki masjid sekira kuatir akan tetesnya darah haid,"},{"k":"rm","h":38,"t":"9. Menulis al-Qur’an menurut sebagian ulama, Sembilan perkara ini yang diharamkan bagi seorang wanita yang sedang haid. Adapun yang tiga selanjutnya, diharamkan bagi lelaki suaminya, yaitu:"},{"k":"rm","h":38,"t":"11. Menceraikan istrinya dalam keadaan haid"},{"k":"rm","h":38,"t":"12. Melakukan istimta’, atau besenang-senang dengan cara memper-mukan kulit antara pusar sampai dengan lutut istrinya dengan selain bersetubuh. Adapun delapan perkara yang lain tidak berupa hukum haram ialah sebagai berikut:"},{"k":"rm","h":39,"t":"2. Kewajiban mandi, setelah haidnya berhenti"},{"k":"rm","h":39,"t":"3. Melaksanakan Iddat, apabila cerai atau suaminya meninggal"},{"k":"rm","h":39,"t":"4. Istibra’ atau menunggu seorang wanita amat yang baru dimiliki"},{"k":"rm","h":39,"t":"6. Diterima ucapannya apabila wanita itu sudah haid"},{"k":"rm","h":39,"t":"7. Gugurnya kewajiban shalat ketika keluar darah haid"},{"k":"rm","h":39,"t":"8. Gugurnya thawaf wada’ ketika dalam keadaan haid. (Hasyiyah Al-jamal ala Syarhi Al-Minhaj: 1/227) Ri’ayatul Himmah: 1/152 153). Peringatan!. Berhubungan dengan orang yang mempunyai hadas besar, dibo-lehkan membaca zikir yang diambil dari al-Qur’an, seperti ketika makan atau minum membaca lafadl “Dengan menyebut nama Allah Tuhan Yang Maha Pengasih dan Maha Penyayang”."},{"k":"rm","h":39,"t":"Ketika menerima nikmat dari Allah Subhaanahu wa Ta’aalaa lalu membaca lafad “Segala puji bagi Allah seru sekalian alam semesta”. Ketika naik kendaraan membaca bacaan al-Qur’an dengan harapan semoga selamat dengan lafad"},{"k":"rm","h":40,"t":", “Maha Suci Dzat yang telah menundukkan semua ini bagi kami sebelumnya tidak mampu mengasainya. Dan sesungguhnya kami akan kembali kepada Tuhan kami,. Sesungguhnya yang mewajibkan kepadamu Alqur’an, benar-benar akan mengembalikan kamu ke tempat kembali”."},{"k":"rm","h":40,"t":"Ketika mendapat musibah atau cobaan sabar dan ridla dengan mengucapkan lafad: Sesungguhnya kami kepunyaan Allah, dan sesungguhnya. kepada Allah lah tempat kami kembali."},{"k":"rm","h":40,"t":"(Al-Iqna’ pada Hamisy Hasyiyah Al-Bujarami:1/315 dan Abyanal Hawaij: 11/269). Masalah Datang dan Hilangnya Mani’. Perkara yang mencegah wajibnya shalat, oleh para ulama ahli fiqih dinamakan dengan Maani’. Bahwa Manik’, jumlahnya ada tujuh macam ialah sebagai berikut:"},{"k":"rm","h":40,"t":"3. Haid (2) nifas (3) Kufur asli (4) Sifat anak (5) Sakit gila (6) Epilepsi (7) Mabuk. Manik-manik yang jumlahnya tujuh macam itu yang lima dapat berulang kembali, seperti: (1) Haid (2) Nifas (3) Sakit gila (4) Epilepsi (5) Mabuk. Adapun kufur asli dan sifat anak, tidak bisa kembali lagi."},{"k":"rm","h":40,"t":"Apabila salah satu manik dari manik-manik itu datang setelah masuk waktu shalat, dengan tenggang waktu yang sekiranya cukup untuk mengerjakan shalat (bagi orang yang sehat), atau cukup untuk mengerjakan shalat dengan bersucinya bagi orang yang kekal hadasnya, atau orang yang tayamum, maka setelah hilangnya manik-manik, ia kewajiban mengqadla shalat waktu datangnya manik–manik itu saja. Tidak kewajiban mengqadla shalat waktu sebelumnya. Atau setelah datangnya manik-manik walaupun boleh di jama’ dengan shalat waktu datangnya manik-manik tersebut (Mirqatus Su’ud: 17, Hasyiyah Al-Kurdi Ala Al-Minhajul Qawim: 1/138)."},{"k":"rm","h":41,"t":"Contohnya: Manik haid atau gila datang jam satu siang sebelum mengerjakan shalat Dluhur, maka wanita yang bersangkutan kewajiban mengqadla shalat Dhuhur saja. Tidak kewajiban mengqadla shalat Shu-buh atau shalat Asharnya. Apabila haid atau gila datang jam empat sore, sebelum mengerjakan shalat Ashar, maka besok ia kewajiban qadla shalat Ashar saja. Tidak kewajiban mengqadla shalat Dhuhur atau shalat Maghribnya. Jadi masalah datangnya haid, nifas, gila, ank are dan mabuk, yang dalam istilah fiqih disebut Jaa’al Maani’, dalam mengqadla shalat tidak dengan bertalian pada shalat sebelumnya, atau shalat yang sesudahnya."},{"k":"rm","h":41,"t":"Peringatan!. Masalah Jaa’al Maani’ ternyata banyak yang salah faham, sehing ga sebagian orang ada yang mewajibkan qadla shalat sebelum datang-nya manik. Dan sebagian orang, ada lagi yang mewajibkan qadla shalat waktu setelah datangnya manik."},{"k":"rm","h":41,"t":"Sebenarnya masalah Jaa’al Maani’, yang dalam mengqadla shalat dapat mewajibkan berantai itu hanya untuk orang yang tidak sehat, yaitu orang yang mempunyai dua manik atau dua halangan."},{"k":"rm","h":41,"t":"Contohnya: Ada seorang gila mulai pagi hingga jam empat sore baru sembuh. Setelah jam setengah lima sore, belum mengerjakan shalat, penyakit gilanya kambuh kembali. Yang demikian ini ia besuk diwajibkan mengqadla shalat Ashar dan shalat Dhuhurnya. Atau ada orang sakit ayan sembuh pada jam sembilan malam. Pada jam sepuluh, sebelum mengerjakan shalat Isya’, ia kedatangan haid."},{"k":"rm","h":41,"t":"Yang demikian inilah ia setelah sembuh diwajibkan mengqadla shalat Isya’ dan shalat Maghribnya (Fathul Wahhab serta Hasyiyat Al-Jamal: 1/294, Sulaiman Al-Kurdy “Ala Al-Minhaj Al-Qawim: 1/138.) Masalah hilangnya manik-manik yang menurut istilah dalam fiqih disebut Zaalal Maani’, atau Zawaalul Maani’aat, ialah dalam mengetahui hukum-hukumnya harus lebih dahulu mengetahui shalat-shalat yang boleh di jama’ dan shalat-shalat yang tidak boleh di jama’ (dikumpulkan). Adapun shalat yang boleh di jama’ itu hanya shalat Dhuhur boleh di jama’ dengan shalat Ashar, dan shalat Maghrib boleh di jama’ dengan shalat Isya’. Shalat Shubuh tidak boleh di jama’ dengan shalat Isya’ atau shalat Dhuhur."},{"k":"rm","h":41,"t":"Dan shalat Ashar tidak boleh di jama’ dengan shalat Maghrib (Al- Taqrib pada Hamisy Fathul Qarib: 17)."},{"k":"rm","h":41,"t":"Bagi seorang yang hilang manik-maniknya pada waktu Dhuhur, Maghrib atau Shubuh, tidak wajib mengqadla shalat yang sebelumnya, karena tidak boleh di jama’. Ia hanya kewajiban mengerjakan shalat waktu itu saja dengan adaa’, sekiranya masih cukup waktunya untuk bersuci dan mengerjakan shalat"},{"k":"rm","h":42,"t":"satu rekaat. Apabila waktunya sudah tidak cukup, maka shalatnya dikerjakan dengan qadla. Apabila hilangnya manik itu pada waktu Ashar atau waktu Isya’, sekalipun hanya waktu yang hanya cukup untuk mengucapkan lafad Takbir, Allaahu Akbar, maka ia kewajiban mengerjakan shalat waktu itu dengan adaa’, sekira waktunya masih cukup untuk besuci dan menger-jakan shalat satu rekaat. Apabila waktunya sudah tidak cukup, maka shalatnya dikerjakan dengan qadla, kecuali ia diwajibkan mengerjakan shalat waktu hilangnya manik-manik. Ia diwajibkan pula mengqadla shalat waktu yang sebelumnya, karena boleh di jama’ (Syarhu Al-Minhaj pada Hamisy Hasyiyah Al-Jamal: 1/279)."},{"k":"rm","h":42,"t":"Contoh-Contoh. 1. Seorang wanita berhenti haid pada jam satu siang, maka ia diwajib-kan shalat Dhuhur saja dengan adaa’ (shalat tepat waktunya)."},{"k":"rm","h":42,"t":"2. Seorang wanita berhenti haid pada waktu Dhuhur tinggal setengah menit, maka ia diwajibkan shalat Dhuhur dengan qadla."},{"k":"rm","h":42,"t":"3. Seorang wanita berhenti haid pada jam empat sore, maka ia diwa-jibkan shalat Ashar dengan adaa’ dan mengqadla shalat Dhuhur."},{"k":"rm","h":42,"t":"4. Seorang wanita berhenti haid pada waktu Ashar hanya tinggal seteng-ah menit, maka ia diwajibkan shalat Ashar dan shalat Dhuhur dengan qadla keduanya."},{"k":"rm","h":42,"t":"Perkara Yang Menyebabkan Kewajiban Mandi. Perkara yang menyebabkan kewajiban mandi itu sebanyak ada enam perkara, dua perkara berlaku bagi kaum wanita dan berlaku pula bagi kaum lelaki, ialah sebagai berikut:"},{"k":"rm","h":42,"t":"1. Mandi jenabat, sebab bersetubuh, walaupun tidak keluar mani, atau keluar mani, walaupun tidak bersetubuh."},{"k":"rm","h":42,"t":"2. Kewajiban mandi disebabkan meninggal dunia, kecuali mati syahid, yaitu mati di medan pertempuran berperang melawan kafir harbi, dan mati karena uzur. Seperti mati terbakar dan sejenisnya."},{"k":"rm","h":42,"t":"Dan yang tiga perkara berlaku hanya untuk kaum wanita yaitu sebagai berikut:"},{"k":"rm","h":42,"t":"3. Sebab mengeluarkan darah haid"},{"k":"rm","h":43,"t":"4. Sebab mengeluarkan darah nifas"},{"k":"rm","h":43,"t":"5. Sebab melahirkan anak, meskipun masih berupa segumpal darah, atau segumpal daging, yakni belum membentuk rupa manusia (Fathul Qaribul Mujib: 6, Husnul Mathalib: 67 dan Kasyifatus Saja: 24)."},{"k":"rm","h":43,"t":"Beberapa-Masalah Penting. 1. Apabila ada seorang wanita selesai bersetubuh dengan suaminya. Setelah mandi, ia keluar dari kemaluannya berupa mani suaminya. Apakah wajib mengulang mandinya atau tidak? Jawabannya: Apabila wanita itu ketika disetubuhi suaminya dalam keadaan syahwat, maka ia diwajibkan untuk mandi lagi, kareana mani yang keluar adalah campuran antara air maninya sendiri dengan mani suaminya. Akan tetapi apabila wanita itu ketika disetubuhi tidak bersyahwat, misalnya sedang tidur nyenyak, maka ia tidak diwajibkan mandi lagi, karena yang keluar itu hanya murni maninya suami (Kasyifatus Saja: 22)."},{"k":"rm","h":43,"t":"2. Apabila seorang wanita di dalam mengeluarkan darah haid terputus-putus. Apakah ia diwajibkan mandi haid? Jawabannya: Apabila dalam mengeluarkan darah belum mencapai cukup 24 jam, maka ia belum diwajibkan mandi. Dan apabila ia mengeluarkan darah sudah cukup 24 jam, maka sewaktu-waktu darahnya berhenti, ia sudah dihukumi suci dari haid, yakni sudah diwajibkan mandi, shalat, puasa serta sudah halal disetubuhi suaminya. Kemudian kalau ternyata darah- nya keluar lagi, maka kenyataan mandi, shalat dan puasanya tidak sah, karena sebenarnya ia masih didalamnya masa haid. Oleh karena itu nantinya ia diwajibkan mengqadla puasa yang dikerjakan didalam berhentinya itu."},{"k":"rm","h":43,"t":"Ia tidak berdosa melakukan persetubuhan di dalam masa berhentinya itu, walaupun sejatinya masih di dalam masa haid, karena hanya melihat pada dhahirnya saja. Seterusnya, sewaktu-waktu darahnya berhenti lagi, maka ia dihukumi suci lagi. Jadi diwajibkan macam-macam lagi. Dan apabila darahnya kembali keluar lagi, maka kenyataannya ia masih di dalam masa haid. Demikian seterusnya, selama belum lebih dari 15 hari dan 15 malam (Al-Jamal ‘Ala Syarhil Minhaj: 1/226)."},{"k":"rm","h":43,"t":"Fardlu-Fardlunya Mandi. Bahwa fardlu-fardlu atau rukun-rukunnya mandi wajib atau sun-ah jumlahnya sebanyak tiga perkara ialah:"},{"k":"rm","h":43,"t":"1. Niat di dalam hati untuk menghilangkan janabat, haid, nifas atau wiladah. Dengan mengguyurkan air ke sebagian anggota badan, misalnya wajah atau yang lain."},{"k":"rm","h":44,"t":"2. Meratakan air ke seluruh kulit tubuh dan rambut. Untuk wanita yang rambutnya digelung atau di pocong, jika tidak bisa sampai dan merata air kedalamnya, maka wajib mengurai rambutnya. Kemudian ketika meratakan air ke seluruh lekuk-lekuk tubuh, wanita yang mandi tidak cukup dengan posisi berdiri, tetapi harus duduk sekira air merata ke seluruh tubuh dan rambut."},{"k":"rm","h":44,"t":"3. Menghilangkan najis dengan air, bila dalam tubuhnya terdapat najis yang nyata. Keterangan ini yang dianggap baik oleh Imam Rafi’i. Oleh karena itu tidak cukup membasuh satu kali untuk menghilangkan hadas dan sekaligus najis, kecuali najis hukmiyah (Ri’ayatal Himmat: 1/151-152)."},{"k":"rm","h":44,"t":"Syarat-Syarat Sah Wudlu dan Mandi. Bahwa syarat-syarat sahnya wudlu dan mandi itu jumlahnya ada sembilan perkara, yaitu:"},{"k":"rm","h":44,"t":"1. Islam. Artinya mandi seseorang dianggap sah, jika ia beragama Islam (mengucapkan dua kalimat Syahadat dengan memenuhi syarat-syaratnya)."},{"k":"rm","h":44,"t":"2. Tamyiz. Artinya mandi seseorang dianggap sah, jika ia berakal sehat. Adapun Tamyiz yang dimaksud, seseorang yang dapat membedakan antara malam dengan siang, atas dengan bawah, arah mata ank a: barat- timur, utara-selatan dan antara suci dengan najis."},{"k":"rm","h":44,"t":"3. Mengetahui pekerjaan yang fardlu dalam wudlu dan mandi. Yaitu fardlu wudlu ada enam perkara dan fardlunya mandi ada tiga perkara."},{"k":"rm","h":44,"t":"4. Air yang digunakan untuk wudlu dan mandi harus dengan air yang. Suci dan mensucikan yang lain."},{"k":"rm","h":44,"t":"5. Tidak ada sesuatu pada lahirnya yang menghalangi sampainya air ke seluruh kulit tubuh anggota wudlu maupun mandi."},{"k":"rm","h":44,"t":"6. Kekal niatnya sampai pada akhir sempurnanya wudlu dan mandi."},{"k":"rm","h":44,"t":"7. Tidak ada sesuatu akibat yang dapat merubahkan sifat air sampai kulit tubuh anggota wudlu atau anggota mandi."},{"k":"rm","h":44,"t":"8. Mengalir airnya hingga sampai ke seluruh ubuh anggota wudlu maupun anggota mandi."},{"k":"rm","h":44,"t":"9. Sudah berhenti dari darah haid, nifas maupun wiladat. Wudlu dan mandi bagi orang yang kekal hadasnya (Daaimul Hadats), syaratnya harus ditambah lagi dua perkara yaitu:"},{"k":"rm","h":45,"t":"10. Wudlu atau mandi harus sesudah masuk waktu shalat."},{"k":"rm","h":45,"t":"11. Dan harus segera dilaksanakan wudlu dan mandi dengan segera. (Minhajul Qawim: 14 dan Ri’ayatal Himmah: 1/147-148).)"}];
